<script setup lang="ts">
import WorkbenchGuide from "../../components/presentation/WorkbenchGuide.vue";
import WorkbenchHeader from "../../components/presentation/WorkbenchHeader.vue";
import JobArtwork from "../../components/base/JobArtwork.vue";
import {computed,ref,onMounted,onBeforeUnmount,watch} from 'vue';
import {workbench} from '../../adapters/repository/http';
import {normalizeMatchPreferences,compareMatchCandidates} from '../../services/workbench-state';
import type {MatchCandidate,MatchResults,MatchPreferences,AiProvenance as Provenance} from '../../types/ai-workbench';
import AppButton from '../../components/base/AppButton.vue';
import AiProvenance from '../../components/business/AiProvenance.vue';
import {aiConsent} from '../../services/ai-consent';
const preferences=ref<MatchPreferences>({role:'',city:'',industry:'',salaryMin:null,strictCity:false}),result=ref<MatchResults|null>(null),busy=ref(false),notice=ref(''),category=ref('all'),sort=ref('ai'),analysis=ref<Record<string,{text:string;provenance?:Provenance}>>({}),analyzing=ref(''),historical=ref(true);
const items=computed(()=>[...(result.value?.items??[])].filter(i=>category.value==='all'||i.category===category.value).sort((a,b)=>sort.value==='ai'?(a.aiRank??Infinity)-(b.aiRank??Infinity)||compareMatchCandidates(a,b):sort.value==='score'?compareMatchCandidates(a,b):b.observedAt.localeCompare(a.observedAt)));
const safeUrl=(value:string)=>{try{const u=new URL(value);return ['http:','https:'].includes(u.protocol)&&!u.username&&!u.password?u.href:'';}catch{return '';}};
let controller:AbortController|undefined,operation=0;
function stop(){operation++;controller?.abort();busy.value=false;analyzing.value='';}
watch(aiConsent,value=>{if(!value){stop();notice.value='AI已关闭，未完成请求已停止。仍可查看历史结果，不会生成规则替代推荐。';}},{flush:'sync'});
onBeforeUnmount(stop);
async function run(discover=false){if(busy.value||analyzing.value)return;if(!aiConsent.value){notice.value='AI已关闭，请在顶部开启后生成推荐。';return;}const current=++operation;controller=new AbortController();busy.value=true;notice.value='';historical.value=true;try{const value=await workbench<MatchResults>('/matches',{preferences:normalizeMatchPreferences(preferences.value),discover,consent:true},controller.signal);if(current!==operation)return;result.value=value;analysis.value={};historical.value=false;}catch{if(current===operation)notice.value='匹配未完成，请检查服务、额度或稍后重试。旧结果仍保留，以下不是本次新结果。';}finally{if(current===operation)busy.value=false;}}
async function explain(item:MatchCandidate){if(busy.value||analyzing.value)return;if(!aiConsent.value){notice.value='AI已关闭，请在顶部开启后分析。';return;}const current=++operation;controller=new AbortController();analyzing.value=item.id;try{const data=await workbench<{text:string;provenance?:Provenance}>('/matches/analyze',{id:item.id,consent:true},controller.signal);if(current===operation)analysis.value[item.id]=data;}catch{if(current===operation)notice.value='本次AI分析未完成，已保存结果未变；如仍显示分析，为上次结果。请核对简历与服务状态。';}finally{if(current===operation)analyzing.value='';}}
function interview(item:MatchCandidate){return {path:'/student/mock/voice',query:{title:item.title.slice(0,160),requirements:(item.description||`${item.title}；具体岗位要求需用户补充核对。`).slice(0,6000),...(safeUrl(item.url)?{sourceUrl:safeUrl(item.url)}:{})}};}
onMounted(async()=>{try{result.value=await workbench<MatchResults>('/matches');if(result.value.preferences)preferences.value=result.value.preferences;}catch{notice.value='尚未取得匹配资料，请点击进行匹配。';}});
</script>
<template>
 <main id="main-content" class="business-page match-page ui-scene ui-scene--journey"><WorkbenchHeader>
      <template #heading><div><p class="kicker">OPPORTUNITY MATCH · 依据可追溯</p><h1>找到方向，也看清差距。</h1><p>DeepSeek基于真实候选资料生成推荐顺序和理由；规则分独立展示，未知信息不视为符合。</p></div></template>
      <template #actions><RouterLink class="inline-link" to="/student/jobs">返回岗位主页面</RouterLink></template>
    </WorkbenchHeader>

    <div class="workbench-split workbench-body-layout"><div class="workbench-body-main">
 <section class="match-form panel"><h2>这次想寻找什么机会？</h2><div class="fields"><label>意向岗位<input v-model="preferences.role" maxlength="100" placeholder="如：前端开发"></label><label>意向城市<input v-model="preferences.city" maxlength="100" placeholder="如：北京"></label><label>意向行业<input v-model="preferences.industry" maxlength="100" placeholder="可选"></label><label>期望月薪最低值（元）<input v-model.number="preferences.salaryMin" type="number" min="0" max="1000000" placeholder="不限"></label></div><label class="check"><input v-model="preferences.strictCity" type="checkbox">排除已知地点不符合的岗位（地点未知仍列为待核验）</label><div class="page-actions"><AppButton :loading="busy" :disabled="!aiConsent" @click="run(false)">进行AI岗位匹配</AppButton><AppButton variant="secondary" :disabled="busy||!preferences.role.trim()||!aiConsent" @click="run(true)">联网发现更多机会</AppButton><RouterLink to="/student/resume/optimize" class="inline-link">先优化简历</RouterLink></div><p class="muted">点击匹配或分析会将脱敏简历、意愿和真实岗位资料发送DeepSeek，可能产生费用；联网发现另调用Search。每次最多30个候选参与模型分析，未推荐条目不补造AI理由。打开页面仅读取历史，不自动付费；取消不能撤回已发送资料或费用。匹配度不是录用概率。</p></section>
 <p v-if="notice" class="business-notice" role="status">{{ notice }}</p>
 <section v-if="result" class="results"><div class="result-toolbar"><div><h2><span>{{ !result.provenance?'尚无AI生成结果':historical?'上次生成的结果':'本次生成结果' }}</span> · {{ result.items.length }}条</h2><p class="muted">{{ result.provenance?new Date(result.asOf).toLocaleString():'尚无生成记录' }} · 关联简历版本 {{ result.resumeVersionId?.slice(0,8)??'尚无已保存简历' }}；简历或意愿变化后请重新匹配。</p></div><div class="filters"><label>显示<select v-model="category"><option value="all">全部结果</option><option value="recommended">规则条件符合</option><option value="verify">待确认机会</option><option value="excluded">条件不符</option></select></label><label>排序<select v-model="sort"><option value="ai">AI推荐顺序优先</option><option value="score">规则匹配度优先</option><option value="recent">资料时间优先</option></select></label></div></div><AiProvenance :value="result.provenance" :historical="historical" />
 <div v-if="!items.length" class="panel"><h3>暂无符合当前筛选的机会</h3><p>调整条件，或明确发起联网发现。系统不会生成不存在的岗位填充结果。</p></div>
 <article v-for="item in items" :key="item.id" class="job-card panel"><div class="job-heading"><JobArtwork :identity="item.id" :title="item.title" /><div><span class="badge">{{ item.category==='recommended'?'规则条件符合':item.category==='excluded'?'条件不符':'待确认机会' }}</span><h3>{{ item.title }}</h3><p>{{ item.employer }} · {{ item.location??'地点未知' }} · {{ item.salaryText }}</p></div><div class="score"><strong>{{ item.score===null?'—':item.score }}</strong><span>{{ item.score===null?'资料不足，不计算总分':'规则匹配参考分' }}</span></div></div><p>{{ item.description||'尚无完整岗位要求，请查看原站。' }}</p><section v-if="item.aiRank" class="ai-recommendation"><h4>AI推荐顺序 #{{ item.aiRank }}</h4><ul><li v-for="reason in item.aiReasons" :key="reason">{{ reason }}</li></ul><p v-if="item.aiGaps?.length">AI提示的差距 / 待核验：{{ item.aiGaps.join('；') }}</p></section><p v-else class="muted">{{ item.category==='excluded'?'硬性条件排除，不参与AI推荐。':'未列入本次AI推荐，不代表已被模型逐项评价。' }}</p><div class="basis"><section><h4>规则事实依据（非AI）</h4><ul v-if="item.reasons.length"><li v-for="reason in item.reasons" :key="reason">{{ reason }}</li></ul><p v-else>暂无足够依据。</p></section><section><h4>规则差距与待核验信息</h4><ul><li v-for="gap in item.gaps" :key="gap">{{ gap }}</li></ul></section></div><p class="muted">{{ item.coverage }} · 来源：{{ item.sourceName }} · 观察时间：{{ new Date(item.observedAt).toLocaleString() }}</p><p v-if="item.category==='verify'" class="muted">外部机会或搜索结果未经逐条招聘资格认证，截止、要求和有效性以原站为准。</p><div class="page-actions"><a v-if="safeUrl(item.url)" :href="safeUrl(item.url)" target="_blank" rel="noopener noreferrer" class="inline-link">前往原站核实 ↗</a><AppButton variant="secondary" size="sm" :loading="analyzing===item.id" :disabled="!!analyzing||!aiConsent" @click="explain(item)">AI分析匹配依据</AppButton><RouterLink :to="interview(item)" class="inline-link">针对此岗位练习面试</RouterLink></div><div v-if="analysis[item.id]" class="analysis"><h4>已生成的AI参考分析</h4><p>{{ analysis[item.id]?.text }}</p><AiProvenance :value="analysis[item.id]?.provenance" /></div></article>
 </section>
    </div><WorkbenchGuide title="每个推荐，都有来路。" copy="岗位事实、规则依据与AI建议分别呈现。资料不足与未知条件不会被当作符合。" /></div>
    </main>
</template>
<style scoped>
.ai-recommendation{margin:18px 0;padding:16px 20px;border:1px solid var(--brand-border,var(--border));border-left:3px solid var(--brand-text);border-radius:12px;background:var(--brand-soft)}.ai-recommendation h4{margin:0;color:var(--brand-text)}.ai-recommendation ul,.ai-recommendation p{font-size:13px;line-height:1.9}.ai-recommendation p{margin-bottom:0}
.match-page{max-width:1180px}.kicker{font-size:12px;color:var(--brand-text);letter-spacing:.08em}.panel{background:var(--surface);border:1px solid var(--border);padding:24px;border-radius:16px;margin:20px 0}.fields{display:grid;grid-template-columns:repeat(4,1fr);gap:16px}.fields label,.filters label{display:flex;flex-direction:column;gap:8px;font-size:13px}input,select{min-height:42px;border:1px solid var(--border-control);border-radius:8px;padding:8px 12px;box-sizing:border-box;background:var(--surface);color:var(--text-1);width:100%;font:inherit}.check{display:flex;align-items:center;gap:8px;font-size:13px;margin:18px 0}.check input{width:16px;min-height:16px}.muted{color:var(--text-2);font-size:12px;line-height:1.7}.result-toolbar,.job-heading{display:flex;justify-content:space-between;gap:20px;align-items:flex-start}.filters{display:flex;gap:12px}.job-heading h3{font-size:22px;margin:12px 0}.badge{background:var(--brand-soft);color:var(--brand-text);font-size:12px;border-radius:20px;padding:5px 10px}.score{display:flex;flex-direction:column;align-items:center;flex-shrink:0;color:var(--text-2);font-size:11px}.score strong{font-size:38px;color:var(--brand-text)}.basis{display:grid;grid-template-columns:1fr 1fr;gap:20px}.basis section{background:var(--surface-2);padding:16px;border-radius:12px}.basis h4{margin:0 0 12px}.basis ul{padding-left:20px;line-height:1.9;font-size:13px}.analysis{border-left:3px solid var(--brand);padding:4px 18px;margin-top:20px}.analysis p{white-space:pre-wrap;line-height:1.8}@media(max-width:800px){.fields{grid-template-columns:1fr 1fr}.basis{grid-template-columns:1fr}.result-toolbar{flex-direction:column}}@media(max-width:500px){.fields{grid-template-columns:1fr}.panel{padding:16px}.job-heading{flex-direction:column}.score{align-items:flex-start}.filters{flex-wrap:wrap}}
</style>
